INSERT INTO `movies` (`id`, `tmdb_id`, `title`, `original_title`, `slug`, `tagline`, `synopsis`, `poster`, `backdrop`, `trailer_url`, `release_date`, `runtime`, `country`, `language`, `budget`, `revenue`, `avg_rating`, `rating_count`, `view_count`, `is_approved`, `status`, `is_featured`, `featured_order`, `created_by_user_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 1226863, 'Phim Super Mario Thiên Hà', 'The Super Mario Galaxy Movie', 'phim-super-mario-thien-ha', '', 'Nối tiếp thành công của phần phim đầu tiên, Mario và Luigi dấn thân vào một cuộc phiêu lưu ngoài sức tưởng tượng khi họ bị cuốn vào không gian sâu thẳm. Lần này, họ gặp gỡ Rosalina, người bảo vệ các vì sao và là \"mẹ\" của những sinh vật Luma đáng yêu. Cả nhóm phải hợp sức để ngăn chặn âm mưu thôn tính toàn bộ vũ trụ của Bowser, khi hắn đang thu thập các Grand Stars để xây dựng một đế chế thiên hà hùng mạnh. Phim hứa hẹn mang đến những màn rượt đuổi nghẹt thở giữa các hành tinh với trọng lực siêu thực và hình ảnh rực rỡ.', 'https://image.tmdb.org/t/p/w500/h1FlxHYiVcZVkIE5XW599ZkV6Sr.jpg', 'https://image.tmdb.org/t/p/w1280/9Z2uDYXqJrlmePznQQJhL6d92Rq.jpg', NULL, '2026-04-01', 98, 'JP', 'en', 110000000, 898795175, 8.0, 6, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:32', '2026-05-08 13:29:24', NULL),
(2, 1523145, 'Твоё сердце будет разбито', 'Твоё сердце будет разбито', 'tvoe-serdce-budet-razbito', '', '', 'https://image.tmdb.org/t/p/w500/iGpMm603GUKH2SiXB2S5m4sZ17t.jpg', 'https://image.tmdb.org/t/p/w1280/1x9e0qWonw634NhIsRdvnneeqvN.jpg', NULL, '2026-03-26', 134, 'RU', 'ru', 0, 0, 5.6, 6, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:32', '2026-04-28 17:25:58', NULL),
(3, 83533, 'Avatar: Lửa và Tro Tàn', 'Avatar: Fire and Ash', 'avatar-lua-va-tro-tan', 'Thế giới Pandora sẽ thay đổi mãi mãi.', 'Sau cuộc chiến tàn khốc với RDA và nỗi mất mát to lớn khi đứa con trai cả hy sinh, Jake Sully và Neytiri phải đối mặt với một mối đe dọa mới trên Pandora: tộc Tro Tàn — một nhóm Na\'vi hung bạo và khát khao quyền lực, do thủ lĩnh tàn nhẫn Varang dẫn dắt. Gia đình Jake buộc phải chiến đấu để sinh tồn và bảo vệ tương lai của Pandora, trong một cuộc xung đột đẩy họ đến giới hạn cuối cùng cả về thể xác lẫn tinh thần.', 'https://image.tmdb.org/t/p/w500/w6DBmG260sCHBQdGzkBIVn9gAQZ.jpg', 'https://image.tmdb.org/t/p/w1280/iN41Ccw4DctL8npfmYg1j5Tr1eb.jpg', 'https://www.youtube.com/watch?v=wIiASgAkk7g', '2025-12-17', 198, 'US', 'en', 350000000, 1490477656, 5.2, 4, 0, 1, 'active', 1, 1, NULL, '2026-04-17 03:56:33', '2026-05-08 13:32:04', NULL),
(4, 687163, 'Thoát Khỏi Tận Thế', 'Project Hail Mary', 'thoat-khoi-tan-the', 'Hai thế giới. Một sứ mệnh sống còn.', 'Mất trí nhớ và lạc lõng trên một con tàu vũ trụ, một phi hành gia khám phá ra rằng anh là hy vọng duy nhất của nhân loại trước bờ vực tuyệt chủng. Một liên minh bất ngờ được hình thành, nắm giữ vận mệnh của tất cả.', 'https://image.tmdb.org/t/p/w500/7NzV9SN5ocWzMrdQw9fFDgLYVJC.jpg', 'https://image.tmdb.org/t/p/w1280/8Tfys3mDZVp4tNoH2ktm06a0Tau.jpg', NULL, '2026-03-15', 157, 'US', 'en', 200000000, 640469765, 7.0, 3, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:35', '2026-05-08 13:33:15', NULL),
(5, 502356, 'Anh Em Super Mario', 'The Super Mario Bros. Movie', 'anh-em-super-mario', '', 'The Super Mario Bros. Movie xoay quanh cuộc phiêu lưu ở thế giới Vương quốc Nấm của anh em thợ sửa ống nước Mario và Luigi. Sau khi tình cờ bước tới vùng đất lạ từ một ống nước, Luigi đã bị chia tách với Mario và rơi vào tay quái vật rùa xấu xa Bowser, hắn đang âm mưu độc chiếm thế giới. Trong lúc cố gắng tìm kiếm người anh em của mình, Mario đã chạm mặt anh bạn nấm Toad và công chúa Peach. Từ đây họ sát cánh bên nhau trên hành trình ngăn chặn thế lực hắc ám.', 'https://image.tmdb.org/t/p/w500/gRlfFcpPdjREQ3lgeuAuB10gfbR.jpg', 'https://image.tmdb.org/t/p/w1280/9n2tJBplPbgR2ca05hS5CKXwP2c.jpg', 'https://www.youtube.com/watch?v=UGO_i2tf1BM', '2023-04-05', 93, 'JP', 'en', 100000000, 1360879735, 8.0, 2, 0, 1, 'active', 1, 2, NULL, '2026-04-17 03:56:36', '2026-04-29 13:13:50', NULL),
(6, 1290417, 'Cá Mập Săn Người', 'Thrash', 'ca-map-san-nguoi', '', 'Dòng nước lũ dữ dội nhuộm đỏ máu khi cư dân mắc kẹt ở thị trấn ven biển chiến đấu để sinh tồn trước cơn siêu bão tàn khốc và bầy cá mập đói khát theo bão kéo đến.', 'https://image.tmdb.org/t/p/w500/adk8weka3O5648g3de4z3y4aE7G.jpg', 'https://image.tmdb.org/t/p/w1280/bPqv6PSsqa2tgO1qb2Gq2iQ1VXf.jpg', NULL, '2026-04-10', 84, 'US', 'en', 0, 0, 8.2, 5, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:36', '2026-05-08 13:47:47', NULL),
(7, 1327819, 'Hoppers: Cú Nhảy Kỳ Diệu', 'Hoppers', 'hoppers-cu-nhay-ky-dieu', 'Hòa mình với thiên nhiên.', 'Các nhà khoa học đã khám phá ra cách \"nhảy\" ý thức con người vào những con vật robot sống động như thật, cho phép con người giao tiếp với động vật dưới hình dạng động vật! Nhờ công nghệ mới này, Mabel sẽ khám phá những bí ẩn trong thế giới động vật vượt xa mọi điều cô từng tưởng tượng.', 'https://image.tmdb.org/t/p/w500/1A7WxXAYddDCrO9dTCEdSzQKU9d.jpg', 'https://image.tmdb.org/t/p/w1280/u53UYu5XG2hNgWGvs3xGhAVzypl.jpg', NULL, '2026-03-04', 105, 'US', 'en', 150000000, 380239139, 8.8, 4, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:37', '2026-05-08 13:32:03', NULL),
(8, 1641319, 'Xạ Thủ Bắn Tỉa: Vô Tổ Quốc', 'Sniper: No Nation', 'xa-thu-ban-tia-vo-to-quoc', '', 'Brandon Beckett và Đặc vụ Zero dẫn đầu một nhiệm vụ giải cứu ở Venezuela khi bạn bè của họ bị bắt làm con tin.', 'https://image.tmdb.org/t/p/w500/tUmARo0TZEK1EaSuS6dU35FhDyU.jpg', 'https://image.tmdb.org/t/p/w1280/7lizs4SuEU2ihkkAa0SZ66NtHbl.jpg', NULL, '2026-04-07', 96, 'US', 'en', 0, 0, 7.3, 6, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:38', '2026-05-08 13:40:40', NULL),
(9, 980431, 'Huyền Thoại Aang: Tiết Khí Sư Cuối Cùng', 'Avatar Aang: The Last Airbender', 'huyen-thoai-aang-tiet-khi-su-cuoi-cung', '', 'Bộ phim tập trung vào giai đoạn hậu chiến tranh, khi thế giới đang trong quá trình tái thiết và đối mặt với những mối đe dọa mới tinh vi hơn từ các tàn dư chính trị. Aang phải gánh vác trọng trách duy trì sự cân bằng giữa bốn quốc gia, đồng thời đối diện với những áp lực của một Thế Thần trưởng thành. Phim hứa hẹn sẽ khai thác sâu hơn về sức mạnh của Aang ở thời kỳ đỉnh cao và mối quan hệ bền chặt của nhóm bạn sau nhiều năm gắn bó.', 'https://image.tmdb.org/t/p/w500/gf7EeEQe22Zu1u55wRT8EAnav93.jpg', 'https://image.tmdb.org/t/p/w1280/sS3zGYFPcfM5pArVNWl6qLyaSmU.jpg', NULL, '2026-10-09', 99, 'US', 'en', 0, 0, 7.6, 3, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:39', '2026-05-08 13:33:12', NULL),
(10, 1290821, 'Kẻ Ẩn Dật', 'Shelter', 'ke-an-dat', 'Không còn đường lui. Nhiệm vụ cuối cùng.', 'Michael Mason, một cựu sát thủ chính phủ đang sống ẩn dật trên một hòn đảo hẻo lánh tại Scotland, tình cờ cứu mạng một cô bé tên Jessie sau một cơn bão dữ dội. Hành động nghĩa hiệp này vô tình khiến tung tích của anh bị lộ, buộc Mason phải đối đầu với những bóng ma từ quá khứ và các đặc vụ MI6 đang truy đuổi gắt gao. Để bảo vệ đứa trẻ, anh phải từ bỏ cuộc sống yên bình, vận dụng mọi kỹ năng sinh tồn và chiến đấu để thoát khỏi vòng vây của những kẻ thù nguy hiểm.', 'https://image.tmdb.org/t/p/w500/mucESEbFFqk3ilVpNxEF53IHIVT.jpg', 'https://image.tmdb.org/t/p/w1280/nHxWyy18SvAZ8jJeemtS8k1UNjM.jpg', NULL, '2026-01-28', 107, 'US', 'en', 50000000, 49754274, 6.7, 4, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:40', '2026-04-28 17:25:58', NULL),
(11, 840464, 'Thảm Họa Thiên Thạch 2: Đại Di Cư', 'Greenland 2: Migration', 'tham-hoa-thien-thach-2-dai-di-cu', '', 'Sau ngày tận thế, gia đình Garrity rời boong-ke an toàn ở Greenland, mạo hiểm tất cả để bước vào một hành trình đầy hiểm nguy, băng qua vùng đất hoang tàn của châu Âu nhằm tìm kiếm một mái nhà mới.', 'https://image.tmdb.org/t/p/w500/o3mnfe0nJuD5oBBbGebN3xGYzaK.jpg', 'https://image.tmdb.org/t/p/w1280/wns4x1GyxCudgOZRyhXKjXVJf3T.jpg', NULL, '2026-01-07', 98, 'GB', 'en', 90000000, 44856736, 7.3, 4, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:41', '2026-04-28 17:25:58', NULL),
(12, 1171145, 'Tội Phạm 101', 'Crime 101', 'toi-pham-101', 'Một phi vụ kết nối tất cả.', 'Lấy bối cảnh thành phố Los Angeles đầy nắng và bụi đường, Tội Phạm 101 kể về một tên trộm nữ trang bí ẩn (Chris Hemsworth) với hàng loạt phi vụ táo bạo khiến cảnh sát phải đau đầu. Trong lúc chuẩn bị cho phi vụ lớn nhất của mình, hắn gặp gỡ một nữ nhân viên bảo hiểm (Halle Berry), người cũng đang vật lộn với những lựa chọn trong đời mình. Trong khi đó, một thanh tra (Mark Ruffalo) đã tìm ra quy luật trong chuỗi các vụ án và đang ráo riết truy đuổi tên trộm, khiến cuộc chơi trở nên căng thẳng hơn bao giờ hết. Khi phi vụ định mệnh đến gần, ranh giới giữa kẻ săn đuổi và con mồi dần trở nên mờ nhạt và cả ba buộc phải đối mặt với những lựa chọn khó khăn và không còn cơ hội để quay đầu lại. Bộ phim được chuyển thể từ tiểu thuyết ngắn nổi tiếng cùng tên của Don Winslow, do Bart Layton (tác giả của American Animals, The Imposter) viết kịch bản và đạo diễn. Dàn diễn viên có sự tham gia của Barry Keoghan, Monica Barbaro, Corey Hawkins, Jennifer Jason Leigh và Nick Nolte.', 'https://image.tmdb.org/t/p/w500/2i7DfVMYX7DyjmQiX64Le8uK45K.jpg', 'https://image.tmdb.org/t/p/w1280/sl2649wlcocfFU7HKxQgNUEBMnT.jpg', NULL, '2026-02-11', 141, 'GB', 'en', 90000000, 72824188, 5.6, 6, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:42', '2026-05-08 13:37:20', NULL),
(13, 1470130, 'Trợ lý nhà xác', 'The Mortuary Assistant', 'tro-ly-nha-xac', '', 'Rebecca Owens, một sinh viên mới tốt nghiệp ngành khoa học nhà xác, nhận công việc ca đêm tại nhà xác River Fields. Ban đầu, công việc có vẻ đơn giản — ướp xác, hoàn thành giấy tờ và giữ gìn vệ sinh. Nhưng khi Rebecca bắt đầu làm ca đêm, mọi chuyện bắt đầu trở nên tăm tối.', 'https://image.tmdb.org/t/p/w500/72AoFPC5TY4DfJwXXS9rPwPeReD.jpg', 'https://image.tmdb.org/t/p/w1280/gM1kQRPwOVW1Eos5tVWqcYmHR5S.jpg', NULL, '2026-02-13', 91, 'US', 'en', 0, 1300011, 6.7, 4, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:43', '2026-05-08 13:37:49', NULL),
(14, 1297842, 'Tuyển Thủ Dê: \"Mùi\" Vị Chiến Thắng', 'GOAT', 'tuyen-thu-de-mui-vi-chien-thang', 'Bạn chẳng bao giờ quá nhỏ để mơ lớn', 'Will là một chú dê nhỏ với những ước mơ lớn, người có được cơ hội duy nhất trong đời để gia nhập các vận động viên chuyên nghiệp và thi đấu môn rugebol — một môn thể thao cường độ cao, pha trộn và đối kháng toàn diện, nơi các loài động vật nhanh nhất và hung dữ nhất thế giới thống trị. Những đồng đội mới của Will không mấy hào hứng khi có một chú dê nhỏ trong đội hình, nhưng Will quyết tâm tạo nên một cuộc cách mạng cho môn thể thao này và chứng minh một lần và mãi mãi rằng: “Nhỏ bé cũng biết chơi!”', 'https://image.tmdb.org/t/p/w500/wZRJ3Q2XRJHov1SS80sTXbfjkz9.jpg', 'https://image.tmdb.org/t/p/w1280/tq3h43fZy0H80vzf47MAY7R9Mxo.jpg', NULL, '2026-02-11', 100, 'US', 'en', 90000000, 190564590, 7.8, 4, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:44', '2026-05-08 13:33:18', NULL),
(15, 1049471, 'Nhân Quả - Outcome', 'Outcome', 'nhan-qua-outcome', '', 'Reef Hawk, \"đứa con cưng\" trên các tấm áp phích của Hollywood từ năm sáu tuổi, đang không ổn chút nào. Khi biết mình bị tống tiền liên quan đến một đoạn video bí ẩn, Reef chủ động thực hiện hành trình chuộc lỗi để sửa chữa sai lầm, đối mặt với bóng ma tâm lý và tránh bị tẩy chay.', 'https://image.tmdb.org/t/p/w500/2Iyn6muxMXAEO87yCA2eUXklW1C.jpg', 'https://image.tmdb.org/t/p/w1280/avwIERZtWiWa34qShf5biDzAVaF.jpg', NULL, '2026-04-06', 84, 'US', 'en', 0, 0, 7.8, 5, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:45', '2026-04-28 17:25:58', NULL),
(16, 1159559, 'Tiếng Thét 7', 'Scream 7', 'tieng-thet-7', 'Chìm trong biển lửa.', 'Sidney Evans (Neve Campbell), nạn nhân sống sót của một vụ thảm sát nhiều năm trước, giờ đang sống hạnh phúc cùng chồng và con gái ở một thị trấn khác thì tên sát nhân Ghostface mới lại xuất hiện. Những nỗi sợ hãi đen tối nhất của cô trở thành hiện thực khi con gái cô Tatum Evans (Isabel May) trở thành mục tiêu tiếp theo. Quyết tâm bảo vệ gia đình, Sidney buộc phải đối mặt với những kinh hoàng trong quá khứ để chấm dứt cuộc đổ máu một lần và mãi mãi.', 'https://image.tmdb.org/t/p/w500/nXXpliMy4Y0mwRa4OlhOb6GyOEE.jpg', 'https://image.tmdb.org/t/p/w1280/t9J2HXaDuJR7bvIG9XF7mttn4VY.jpg', 'https://www.youtube.com/watch?v=Woryikdu1v0', '2026-02-25', 114, 'US', 'en', 45000000, 213835967, 5.4, 2, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:46', '2026-05-08 13:37:50', NULL),
(17, 1311031, 'Thanh Gươm Diệt Quỷ: Vô Hạn Thành', '劇場版「鬼滅の刃」無限城編 第一章 猗窩座再来', 'thanh-guom-diet-quy-vo-han-thanh', 'Khai Hỏa Trận Chiến Cuối Cùng', 'Khi các thành viên của Sát Quỷ Đoàn và Trụ Cột tham gia vào chương trình đặc huấn để chuẩn bị cho trận chiến sắp với lũ quỷ, Kibutsuji Muzan xuất hiện tại Dinh thự Ubuyashiki. Khi thủ lĩnh của Sát Quỷ Đoàn gặp nguy hiểm, Tanjiro và các Trụ Cột trở về trụ sở Thế nhưng, Muzan bất ngờ kéo toàn bộ Sát Quỷ Đoàn đến hang ổ cuối cùng của lũ quỷ là Vô Hạn Thành, mở màn cho trận đánh cuối cùng của cả hai phe.', 'https://image.tmdb.org/t/p/w500/nV99ACeAa8fFFso0tQZ3HktEf5X.jpg', 'https://image.tmdb.org/t/p/w1280/1RgPyOhN4DRs225BGTlHJqCudII.jpg', NULL, '2025-07-18', 155, 'JP', 'ja', 20000000, 733030221, 7.8, 6, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:47', '2026-04-28 17:25:58', NULL),
(18, 1265609, 'Cỗ máy chiến tranh', 'War Machine', 'co-may-chien-tranh', '', 'Trong nhiệm vụ cuối cùng của khóa huấn luyện Biệt kích Lục quân, một kỹ sư chiến đấu phải dẫn dắt đơn vị chống lại một cỗ máy giết người khổng lồ đến từ thế giới khác.', 'https://image.tmdb.org/t/p/w500/n1IwU8lLbvPZXqjfO7PYKzsmNXe.jpg', 'https://image.tmdb.org/t/p/w1280/6yeVcxFR0j08vlv2OlL6zbewm4D.jpg', NULL, '2026-02-12', 110, 'AU', 'en', 73000000, 0, 6.3, 6, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:47', '2026-04-28 17:25:58', NULL),
(19, 1084577, 'Balls Up', 'Balls Up', 'balls-up', '', '', 'https://image.tmdb.org/t/p/w500/xwvJ3WzdJ1OCuDoY8LAxBUlQyig.jpg', 'https://image.tmdb.org/t/p/w1280/jRsjWwZzI39bTm44FNhRtiICd9k.jpg', NULL, '2026-04-15', 104, 'US', 'en', 0, 0, 8.5, 3, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:48', '2026-04-28 17:25:58', NULL),
(20, 1526650, 'Oán Thai Đòi Mẹ', '泥娃娃', 'oan-thai-doi-me', '', 'Khi phát triển trò chơi kinh dị, Húc Xuyên vô tình mang con búp bê đất sét bị vỡ từ chỗ làm về nhà, không hay biết rằng nó chứa một linh hồn oán hận đang khao khát được giải thoát.', 'https://image.tmdb.org/t/p/w500/3epkiHj6FacptxIfRiDZFQXUyL7.jpg', 'https://image.tmdb.org/t/p/w1280/pmGkvEWKFDapogIzkG7TqB0aeYE.jpg', NULL, '2025-10-09', 111, 'TW', 'zh', 0, 0, 5.2, 2, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:49', '2026-04-28 17:25:58', NULL),
(21, 1159831, 'Cô Dâu!', 'The Bride!', 'co-dau', 'Có một quái vật bên trong tất cả chúng ta.', 'Một cách tiếp cận táo bạo, phá vỡ mọi khuôn mẫu đối với một trong những câu chuyện hấp dẫn nhất thế giới. Bộ phim theo chân Frankenstein cô đơn (do Chrisitian Bale thủ vai) lên đường đến Chicago những năm 1930 để tìm đến nhà khoa học Dr. Euphronious (Annette Bening – 5 lần đề cử Oscar thủ vai), với hy vọng bà có thể tạo ra một người bạn đồng hành cho mình. Cả hai hồi sinh một cô gái trẻ đã bị sát hại, và Cô Dâu (Buckley thủ vai) đã ra đời. Những gì xảy ra sau đó đã vượt xa mọi tưởng tượng của họ: những vụ giết người, sự chiếm hữu, một phong trào văn hóa hoang dại và cấp tiến cũng như mối tình ngoài vòng pháp luật đầy cuồng nhiệt và bùng nổ!', 'https://image.tmdb.org/t/p/w500/60PGmrPEUId7KJQb17AAMsItMMJ.jpg', 'https://image.tmdb.org/t/p/w1280/l8rKKMU2M9dDULO9CEtDNdWAEUJ.jpg', NULL, '2026-03-04', 127, 'US', 'en', 80000000, 23744025, 8.3, 5, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:51', '2026-04-28 17:25:58', NULL),
(22, 1084242, 'Phi Vụ Động Trời 2', 'Zootopia 2', 'phi-vu-dong-troi-2', '', 'Trong bộ phim \"Zootopia 2 - Phi Vụ Động Trời 2\" từ Walt Disney Animation Studios, hai thám tử Judy Hopps (lồng tiếng bởi Ginnifer Goodwin) và Nick Wilde (lồng tiếng bởi Jason Bateman) bước vào hành trình truy tìm một sinh vật bò sát bí ẩn vừa xuất hiện tại Zootopia và khiến cả vương quốc động vật bị đảo lộn. Để phá được vụ án, Judy và Nick buộc phải hoạt động bí mật tại những khu vực mới lạ của thành phố – nơi mối quan hệ đồng nghiệp của họ bị thử thách hơn bao giờ hết.', 'https://image.tmdb.org/t/p/w500/5wXpOF9WPUKliIzNBdAqwAStLHU.jpg', 'https://image.tmdb.org/t/p/w1280/lgotja3xMoJZbynwHfcQcJAEMWH.jpg', 'https://www.youtube.com/watch?v=4iWVnVg33Pc', '2025-11-26', 108, 'US', 'en', 150000000, 1868208796, 6.7, 5, 0, 1, 'active', 1, 3, NULL, '2026-04-17 03:56:52', '2026-04-29 13:13:50', NULL),
(23, 1084187, 'Khá nguy hiểm', 'Pretty Lethal', 'kha-nguy-hiem', '', 'Một đoàn vũ công ba lê phải chiến đấu để sinh tồn khi cố gắng trốn thoát khỏi một quán trọ hẻo lánh sau khi xe buýt của họ bị hỏng trên đường đến một cuộc thi khiêu vũ.', 'https://image.tmdb.org/t/p/w500/znTPnXCK3lEQJgqXCvP7e5FUz6f.jpg', 'https://image.tmdb.org/t/p/w1280/z3bzhmC0CPikWeerUkLO73YvGrC.jpg', NULL, '2026-03-13', 89, 'US', 'en', 0, 0, 8.4, 5, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:53', '2026-04-28 17:25:58', NULL),
(24, 1193501, 'Tiếng Còi Tử Thần', 'Whistle', 'tieng-coi-tu-than', '', 'Một nhóm học sinh trung học lạc lõng tình cờ phát hiện một chiếc còi tử thần cổ xưa của người Aztec. Họ sớm nhận ra rằng mỗi khi thổi chiếc còi này, âm thanh kinh hoàng phát ra sẽ triệu hồi chính cái chết trong tương lai của họ quay lại săn lùng. Khi số người thiệt mạng ngày càng tăng, cả nhóm buộc phải lần theo nguồn gốc của di vật chết chóc ấy, trong nỗ lực tuyệt vọng nhằm chấm dứt chuỗi sự kiện kinh hoàng mà chính họ đã vô tình khởi động.', 'https://image.tmdb.org/t/p/w500/eGxPyseSnEZBMJaopGfRUO9HSYx.jpg', 'https://image.tmdb.org/t/p/w1280/u1tUWb3W6nIzVzUQxx54TMq9kIq.jpg', NULL, '2026-01-20', 100, 'IE', 'en', 2000000, 4667629, 6.2, 5, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:54', '2026-05-08 13:55:56', NULL),
(25, 1418657, 'The Yeti', 'The Yeti', 'the-yeti', '', '', 'https://image.tmdb.org/t/p/w500/zaqEfoKcWkVni2eONhJ7DRhMO8Q.jpg', 'https://image.tmdb.org/t/p/w1280/1ytf7rzkZ7RLlMnBdGggQ0ENe6z.jpg', NULL, '2026-04-04', 93, 'US', 'en', 0, 0, 6.2, 6, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:55', '2026-04-28 17:25:58', NULL),
(26, 1268127, 'Humint', '휴민트', 'humint', '', 'Trong khi truy quét đường dây ma túy ở Nga, đặc vụ Hàn Quốc nọ phải hợp tác với một đặc vụ Triều Tiên, rồi tình yêu với người đó thử thách lòng trung thành của anh.', 'https://image.tmdb.org/t/p/w500/f7sCSLEPRfV2fWQ0RYOtHhnHXuG.jpg', 'https://image.tmdb.org/t/p/w1280/5KFThZkdBEQkp9gPWWWNb5CI5yD.jpg', NULL, '2026-02-11', 120, 'KR', 'ko', 16000000, 13207600, 6.7, 5, 0, 1, 'active', 0, 0, NULL, '2026-04-17 03:56:56', '2026-04-28 17:25:58', NULL),
