INSERT INTO `tv_shows` (`id`, `tmdb_id`, `title`, `original_title`, `slug`, `tagline`, `synopsis`, `poster`, `backdrop`, `trailer_url`, `first_air_date`, `last_air_date`, `number_of_seasons`, `number_of_episodes`, `episode_runtime`, `networks`, `type`, `tmdb_status`, `country`, `language`, `avg_rating`, `rating_count`, `view_count`, `is_approved`, `status`, `is_featured`, `featured_order`, `created_by_user_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 76479, 'The Boys', 'The Boys', 'the-boys', 'Đừng bao giờ gặp anh hùng của bạn.', 'Trong một thế giới mà các siêu anh hùng chìm trong mặt tối của sự nổi tiếng và danh vọng to lớn của họ, THE BOYS tập trung vào một nhóm tự phát được biết đến với cái tên không chính thức là nhóm “Trai điên”, những người đặt ra mục tiêu hạ gục các siêu anh hùng tồi tệ này chỉ với sự gan góc và sẵn sàng chơi bẩn của họ.', 'https://image.tmdb.org/t/p/w500/in1R2dDc421JxsoRWaIIAqVI2KE.jpg', 'https://image.tmdb.org/t/p/w1280/bq28ajZaoMyzEIm6REelqyqtEDZ.jpg', 'https://www.youtube.com/watch?v=HlsLSNiRf18', '2019-07-25', '2026-05-06', 5, 40, NULL, '[{\"id\":1024,\"name\":\"Prime Video\",\"logo_path\":\"\\/w7HfLNm9CWwRmAMU58udl2L7We7.png\",\"logo_url\":\"https:\\/\\/image.tmdb.org\\/t\\/p\\/w185\\/w7HfLNm9CWwRmAMU58udl2L7We7.png\"}]', 'Scripted', 'Returning Series', 'US', 'en', 0.0, 0, 0, 1, 'active', 1, 4, NULL, '2026-04-20 14:58:30', '2026-05-08 13:30:20', NULL),
(2, 124364, 'Bẫy', 'FROM', 'bay', '', 'Làm sáng tỏ bí ẩn về một thành phố ở Trung Mỹ giam giữ tất cả những ai bước vào. Khi các cư dân đấu tranh để trở  lại bình thường và tìm kiếm một lối thoát, họ cũng phải sống sót trước các mối đe dọa của khu rừng xung quanh.', 'https://image.tmdb.org/t/p/w500/pRtJagIxpfODzzb0T0NAvZSzErC.jpg', 'https://image.tmdb.org/t/p/w1280/auyEi4Xho43HFvVQnd42LzqBdiV.jpg', NULL, '2022-02-20', '2026-05-03', 4, 40, NULL, '[{\"id\":922,\"name\":\"Epix\",\"logo_path\":\"\\/9aH86hGHVQfvhAqrDRv1EINoxua.png\",\"logo_url\":\"https:\\/\\/image.tmdb.org\\/t\\/p\\/w185\\/9aH86hGHVQfvhAqrDRv1EINoxua.png\"},{\"id\":6219,\"name\":\"MGM+\",\"logo_path\":\"\\/4umnsbif8tOc6ILCmeO0pqRXWFP.png\",\"logo_url\":\"https:\\/\\/image.tmdb.org\\/t\\/p\\/w185\\/4umnsbif8tOc6ILCmeO0pqRXWFP.png\"}]', 'Scripted', 'Returning Series', 'US', 'en', 0.0, 0, 0, 1, 'active', 0, 0, NULL, '2026-04-20 15:09:18', '2026-05-08 13:40:44', NULL),
(3, 85552, 'Lâng Lâng', 'Euphoria', 'lang-lang', '', 'Một nhóm học sinh trung học đang lần tìm hướng đi trong tình yêu và tình bạn giữa một thế giới tràn đầy ma túy, tình dục, đau khổ và truyền thông xã hội hỗn loạn.', 'https://image.tmdb.org/t/p/w500/ya0Vhu5txIlGt7G54E83SqU42ya.jpg', 'https://image.tmdb.org/t/p/w1280/mez2Z3WqlPKNXpi7mWoiiE5guE9.jpg', NULL, '2019-06-16', '2026-05-03', 3, 24, NULL, '[{\"id\":49,\"name\":\"HBO\",\"logo_path\":\"\\/tuomPhY2UtuPTqqFnKMVHvSb724.png\",\"logo_url\":\"https:\\/\\/image.tmdb.org\\/t\\/p\\/w185\\/tuomPhY2UtuPTqqFnKMVHvSb724.png\"}]', 'Scripted', 'Returning Series', 'US', 'en', 0.0, 0, 0, 1, 'active', 0, 0, NULL, '2026-04-20 15:09:19', '2026-05-08 13:40:46', NULL),
(4, 79744, 'Lính Mới', 'The Rookie', 'linh-moi', '', 'Một sự cố thay đổi cuộc đời thúc đẩy người đàn ông 45 tuổi theo đuổi ước mơ làm cảnh sát. Nhưng để được nhận, anh phải chứng minh năng lực với cấp trên tại Sở Cảnh sát Los Angeles.', 'https://image.tmdb.org/t/p/w500/2JovL0r7nz4BRgxfbGkf8oK3oGF.jpg', 'https://image.tmdb.org/t/p/w1280/6iNWfGVCEfASDdlNb05TP5nG0ll.jpg', NULL, '2018-10-16', '2026-05-04', 9, 144, NULL, '[{\"id\":2,\"name\":\"ABC\",\"logo_path\":\"\\/2uy2ZWcplrSObIyt4x0Y9rkG6qO.png\",\"logo_url\":\"https:\\/\\/image.tmdb.org\\/t\\/p\\/w185\\/2uy2ZWcplrSObIyt4x0Y9rkG6qO.png\"}]', 'Scripted', 'Returning Series', 'US', 'en', 0.0, 0, 0, 1, 'active', 0, 0, NULL, '2026-04-20 15:09:20', '2026-05-08 13:40:45', NULL),
(5, 95557, 'BẤT KHẢ CHIẾN BẠI', 'INVINCIBLE', 'bat-kha-chien-bai', '', 'Invincible là series hoạt hình siêu anh hùng dành cho người lớn được chuyển thể từ truyện tranh cùng tên của Skybound/Image Comic do Robert Kirkman sáng tác. Phim được lên kế hoạch kéo dài trong 3 mùa và sẽ phát sóng thông qua nền tảng Amazon Prime Video.\n\nInvincible là câu chuyện xoay quanh Mark Grayson, con trai của anh hùng mạnh nhất hành tinh - Omni-Man. Sau khi vừa tròn 17 tuổi, Mark bắt đầu thức tỉnh sức mạnh của riêng mình. Dưới sự giám hộ của Omni-Man, Mark dấn thân vào con đường trở thành siêu anh hùng và đối đầu với thử thách cam go.', 'https://image.tmdb.org/t/p/w500/4tblBrslcKSifMVZ3TmtT2ukMor.jpg', 'https://image.tmdb.org/t/p/w1280/9qrroces8C6R9aKr08hACNPVXdZ.jpg', NULL, '2021-03-25', '2026-04-22', 5, 32, NULL, '[{\"id\":1024,\"name\":\"Prime Video\",\"logo_path\":\"\\/w7HfLNm9CWwRmAMU58udl2L7We7.png\",\"logo_url\":\"https:\\/\\/image.tmdb.org\\/t\\/p\\/w185\\/w7HfLNm9CWwRmAMU58udl2L7We7.png\"}]', 'Scripted', 'Returning Series', 'US', 'en', 0.0, 0, 0, 1, 'active', 0, 0, NULL, '2026-04-20 15:09:20', '2026-05-08 13:41:07', NULL),
