INSERT INTO `user_titles` (`id`, `name`, `color_hex`, `description`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Tín Đồ Retro', '#8E8E8E', 'Dành cho những tâm hồn hoài niệm, luôn tìm kiếm vẻ đẹp điện ảnh từ những thước phim kinh điển nhuốm màu thời gian.', 1, '2026-05-09 03:30:19', '2026-05-09 03:38:47'),
(2, 'Sứ Giả Nghệ Thuật', '#FF69B4', 'Trao tặng cho người truyền cảm hứng, mang những tác phẩm điện ảnh độc đáo chắp cánh bay xa đến với cộng đồng.', 1, '2026-05-09 03:38:35', '2026-05-09 03:42:59'),
(3, 'Mọt Phim Hảo Ngọt', '#FFB6C1', 'Kẻ say mê tin tức, luôn trực chờ trên diễn đàn để \"nhâm nhi\" những thông tin và drama nóng hổi nhất của giới giải trí.', 1, '2026-05-09 03:43:46', '2026-05-09 03:44:06'),
(5, 'Chúa Tể Giao Lưu', '#FFA500', 'Dành riêng cho cây hài của diễn đàn, nơi nào có mặt là nơi đó rôm rả tiếng cười và những màn \"chém gió\" không hồi kết.', 1, '2026-05-09 03:58:30', '2026-05-09 03:58:30'),
(6, 'Bậc Thầy Đào Mộ', '#8B4513', 'Trao cho những \"nhà khảo cổ\" tận tụy, chậm mà chắc, không bao giờ bỏ lỡ những bài review hay dù chúng đã chìm sâu dưới lớp bụi thời gian.', 1, '2026-05-09 03:59:06', '2026-05-09 03:59:06'),
(7, 'Đôi Mắt Cú Vọ', '#FFD700', 'Chứng nhận cho những nhà phê bình sắc sảo, soi kỹ từng khung hình và không bỏ sót bất kỳ easter egg hay hạt sạn nào trong phim.', 1, '2026-05-09 03:59:24', '2026-05-09 03:59:24'),
(8, 'Kẻ Dẫn Đầu Xu Hướng', '#00FFFF', 'Biểu tượng của dân chơi điện ảnh thực thụ, luôn \"đu trend\" thần tốc và có mặt ở mọi bộ phim hot nhất phòng vé tuần.', 1, '2026-05-09 03:59:50', '2026-05-09 03:59:50'),
(9, 'Vựa Muối Điện Ảnh', '#FFE135', 'Vinh danh những thành viên mang cả vựa muối, biến mỗi góc bình luận thành một sân khấu tấu hài đặc sắc.', 1, '2026-05-09 04:00:07', '2026-05-09 04:00:07'),
(10, 'Mầm Non Gắn Kết', '#32CD32', 'Kỷ niệm cho những thành viên kiên trì nhất, từng ngày ươm mầm đam mê và gắn bó bền chặt với cộng đồng phim ảnh.', 1, '2026-05-09 04:00:41', '2026-05-09 04:00:41'),
(11, 'Hệ Chữa Lành', '#CD853F', 'Dành cho những \"bộ trưởng ngoại giao\" hiền lành, luôn lan tỏa năng lượng tích cực và được lòng cả diễn đàn.', 1, '2026-05-09 04:01:06', '2026-05-09 04:01:06');
